const base = $('Preparar contexto Don Ramon').first().json;
const response = $input.first().json ?? {};
const context = response.data ?? {};
const business = context.business ?? {};
const clean = (value) => String(value ?? '').replace(/\s+/g, ' ').trim();
const lines = [
  '=== MENSAJE DEL CLIENTE ===',
  clean(base.text),
  '',
  '=== IDENTIFICACIÓN DEL CLIENTE ===',
  `Nombre: ${clean(base.name || 'No informado')}`,
  `Teléfono: ${clean(base.phone || 'No informado')}`,
  `Lead ID: ${clean(base.leadId || 'No informado')}`,
  `Condición comercial: ${clean(base.commercialCondition || 'Sin definir')}`,
  '',
  '=== INFORMACIÓN COMERCIAL ===',
];
for (const item of context.knowledge ?? []) {
  lines.push(`TEMA: ${clean(item.title)}`, clean(item.content), '');
}
for (const offer of business.offers ?? []) {
  lines.push(`OFERTA: ${clean(offer.title || offer.name)} | Precio: $${offer.price ?? '-'}`);
}
if (business.superOffer?.active) {
  lines.push(`SUPEROFERTA: ${clean(business.superOffer.title)} | Precio: $${business.superOffer.price ?? '-'}`);
}
if (business.delivery) {
  lines.push(`ENVÍO: ${clean(business.delivery.coverage)}`, `MÍNIMO: $${business.delivery.minimumOrder ?? 0}`, `CORTE COLONIA AVELLANEDA: ${clean(business.delivery.orderCutoffs?.coloniaAvellaneda)}`, `CORTE SAN BENITO: ${clean(business.delivery.orderCutoffs?.sanBenito)}`);
}
lines.push('', '=== LOCALES Y HORARIOS ===');
for (const branch of business.branches ?? []) {
  lines.push(`LOCAL: ${clean(branch.name)}`, `DIRECCIÓN: ${clean(branch.address)}`, `HORARIOS: ${clean(branch.hours?.weekdays)}`, `SÁBADOS: ${clean(branch.hours?.saturday)}`, `DOMINGOS: ${clean(branch.hours?.sunday)}`, `RETIRO: ${clean(branch.hours?.pickup)}`, `WHATSAPP: ${clean(branch.hours?.whatsapp)}`, '');
}
lines.push('', '=== PRODUCTOS DEL CATÁLOGO ===');
const products = Array.isArray(business.products) ? business.products : [];
const isCatalogRequest = /\blista\b|\bcatalogo\b|\bcatalog\b|\btodos\b|\bproductos\b|\bprecios\b/i.test(base.text ?? '');
const selected = products.filter((product) => product.available).slice(0, isCatalogRequest ? 60 : 30);
for (const product of selected) {
  lines.push(`${clean(product.name)} | ID: ${clean(product.id)} | Precio: $${product.price ?? '-'} | Estado: ${Number(product.stock) > 0 ? 'DISPONIBLE' : 'SIN STOCK'} | Categoría: ${clean(product.category)}`);
}
if (selected.length === 0) lines.push('No se encontraron productos relevantes en el contexto recibido.');
const aiInput = lines.join('\n').slice(0, 30000);
return [{ json: { ...base, contextAvailable: Boolean(context.business), shouldReply: context.assistant?.shouldReply === true, aiInput } }];
